const body = $input.first().json.body;
const required = ['book_title', 'author'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const levels = ['high_school', 'undergraduate', 'general_adult', 'literary', 'professional'];
const level = levels.includes(body.discussion_level) ? body.discussion_level : 'general_adult';
return [{ json: {
  valid: true,
  bookTitle: body.book_title.trim(),
  author: body.author.trim(),
  genre: body.genre || '',
  publicationYear: body.publication_year || '',
  groupSize: parseInt(body.group_size) || 8,
  meetingDuration: parseInt(body.meeting_duration_minutes) || 90,
  discussionLevel: level,
  hasReadBook: body.has_read_book !== false,
  specificThemes: (body.specific_themes || '').slice(0, 400),
  avoidSpoilers: body.avoid_spoilers === true || body.avoid_spoilers === 'true',
  groupDescription: (body.group_description || '').slice(0, 300),
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

const search = $('Research Book').first().json;
const input = $('Validate Input').first().json;
const context = (search.results||[]).map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,350)}`).join('\n\n');
return [{ json: { input, bookContext: context || 'Use your general knowledge.' } }];

values.content:
Create a book club discussion guide.

Book: {{ $json.input.bookTitle }} by {{ $json.input.author }}
Genre: {{ $json.input.genre || 'not specified' }}
Publication year: {{ $json.input.publicationYear || 'not specified' }}
Group size: {{ $json.input.groupSize }} people
Meeting duration: {{ $json.input.meetingDuration }} minutes
Discussion level: {{ $json.input.discussionLevel.replace('_',' ') }}
Facilitator has read the book: {{ $json.input.hasReadBook }}
Specific themes to explore: {{ $json.input.specificThemes || 'none specified' }}
Avoid spoilers: {{ $json.input.avoidSpoilers }}
Group description: {{ $json.input.groupDescription || 'general book club' }}

Book research context:
{{ $json.bookContext }}

Return this JSON:
{
  "book_title": "{{ $json.input.bookTitle }}",
  "author": "{{ $json.input.author }}",
  "guide_overview": "2-3 sentences on what makes this book rich for discussion — what tensions, questions, and themes make it especially good for a group",
  "content_warnings": ["any themes that facilitators should be aware of before the meeting — violence, trauma, sensitive topics"],
  "meeting_structure": [
    {
      "segment": "Opening (first N minutes)",
      "duration_minutes": 10,
      "purpose": "what this segment accomplishes",
      "facilitator_prompt": "exactly what the facilitator says to open this segment"
    }
  ],
  "discussion_questions": {
    "opening": [
      {
        "question": "question text",
        "purpose": "what kind of thinking this unlocks",
        "follow_up": "a natural follow-up if the group gives a short answer"
      }
    ],
    "core": [
      {
        "question": "question text",
        "purpose": "what this probes",
        "follow_up": "follow-up prompt",
        "discussion_note": "how to handle if the group gets stuck or goes off track"
      }
    ],
    "thematic": [
      {
        "question": "question that connects the book to bigger ideas or the readers' lives",
        "purpose": "why this matters beyond the text",
        "follow_up": "follow-up"
      }
    ],
    "closing": [
      {
        "question": "closing question — often reflective or personal",
        "purpose": "how this wraps the conversation"
      }
    ]
  },
  "passages_for_close_reading": [
    {
      "description": "describe the passage by chapter/section without spoiling it",
      "why_useful": "what this passage reveals that's worth discussing"
    }
  ],
  "facilitator_tips": ["3-4 practical tips for running THIS book's discussion specifically — not generic facilitation advice"],
  "if_conversation_stalls": "specific thing the facilitator can say or do if energy drops",
  "recommended_pairings": ["1-2 other books, films, or essays that pair well for comparison or as background reading"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let guide;
try { guide = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
guide._meta = { meetingDuration: input.meetingDuration, groupSize: input.groupSize, discussionLevel: input.discussionLevel, replyEmail: input.replyEmail };
return [{ json: guide }];

const g = $input.first().json;
const m = g._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const qBlock = (title, questions, color) => {
  if (!questions || !questions.length) return '';
  const qs = questions.map((q,i) => `
    <div style="border-left:3px solid ${color};padding:12px 16px;margin-bottom:12px;background:#fafafa;border-radius:0 6px 6px 0">
      <div style="font-size:15px;font-weight:600;color:#1a1a1a;margin-bottom:5px">${i+1}. ${esc(q.question)}</div>
      ${q.purpose ? `<div style="font-size:12px;color:#9ca3af;margin-bottom:4px">↳ ${esc(q.purpose)}</div>` : ''}
      ${q.follow_up ? `<div style="font-size:13px;color:#6b7280;font-style:italic">Follow-up: ${esc(q.follow_up)}</div>` : ''}
      ${q.discussion_note ? `<div style="font-size:12px;color:#d97706;margin-top:5px">💡 ${esc(q.discussion_note)}</div>` : ''}
    </div>`).join('');
  return `<div style="margin-bottom:24px">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:${color};margin-bottom:10px">${esc(title)}</div>
    ${qs}
  </div>`;
};

const structureRows = (g.meeting_structure||[]).map(seg => `
  <div style="display:flex;gap:12px;padding:10px 0;border-bottom:1px solid #f3f4f6;align-items:flex-start">
    <div style="min-width:60px;text-align:center;background:#f3f4f6;border-radius:6px;padding:6px 8px">
      <div style="font-size:18px;font-weight:700;color:#1a1a1a">${seg.duration_minutes}</div>
      <div style="font-size:10px;color:#9ca3af;text-transform:uppercase">min</div>
    </div>
    <div>
      <div style="font-size:14px;font-weight:600">${esc(seg.segment)}</div>
      <div style="font-size:13px;color:#6b7280;margin-top:2px">${esc(seg.purpose)}</div>
      ${seg.facilitator_prompt ? `<div style="font-size:13px;color:#2563eb;margin-top:4px;font-style:italic">"${esc(seg.facilitator_prompt)}"</div>` : ''}
    </div>
  </div>`).join('');

const passages = (g.passages_for_close_reading||[]).map(p => `
  <div style="border:1px solid #e5e7eb;border-radius:6px;padding:12px 16px;margin-bottom:10px">
    <div style="font-size:14px;font-weight:600">${esc(p.description)}</div>
    <div style="font-size:13px;color:#6b7280;margin-top:4px">${esc(p.why_useful)}</div>
  </div>`).join('');

const tipsList = (g.facilitator_tips||[]).map(t => `<li style="font-size:14px;margin-bottom:7px;line-height:1.55;color:#374151">${esc(t)}</li>`).join('');
const warnings = (g.content_warnings||[]).length ? `<div style="background:#fffbeb;padding:12px 20px;border:1px solid #fde68a;border-top:none">
  <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:5px">Content notes for facilitators</div>
  ${(g.content_warnings||[]).map(w => `<div style="font-size:13px;color:#78350f;padding:3px 0">${esc(w)}</div>`).join('')}
</div>` : '';

const pairings = (g.recommended_pairings||[]).map(p => `<div style="font-size:13px;color:#374151;padding:5px 0;border-bottom:1px solid #f3f4f6">${esc(p)}</div>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f0f8;font-family:Georgia,'Times New Roman',serif;color:#1a1a1a">
<div style="max-width:700px;margin:0 auto">
  <div style="background:#2d1b4e;color:#fff;padding:22px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#9b7fd4;margin-bottom:5px">Book Club Discussion Guide · ${esc(m.discussionLevel.replace(/_/g,' '))} · ${m.meetingDuration} min · ${m.groupSize} people</div>
    <div style="font-size:22px;font-weight:700;line-height:1.3">${esc(g.book_title)}</div>
    <div style="font-size:15px;color:#9b7fd4;margin-top:4px">by ${esc(g.author)}</div>
  </div>
  ${warnings}
  <div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:none">
    <p style="font-size:15px;line-height:1.75;color:#374151;margin:0">${esc(g.guide_overview)}</p>
  </div>
  ${structureRows ? `<div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f0eaf8">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:12px">Meeting structure</div>
    ${structureRows}
  </div>` : ''}
  <div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f0eaf8">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:16px">Discussion questions</div>
    ${qBlock('Opening — ease in', g.discussion_questions?.opening, '#6b7280')}
    ${qBlock('Core — the meat of it', g.discussion_questions?.core, '#2563eb')}
    ${qBlock('Thematic — bigger picture', g.discussion_questions?.thematic, '#7c3aed')}
    ${qBlock('Closing — reflect and land', g.discussion_questions?.closing, '#16a34a')}
  </div>
  ${passages ? `<div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f0eaf8">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Passages worth reading aloud</div>
    ${passages}
  </div>` : ''}
  ${tipsList ? `<div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f0eaf8">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Facilitator tips for this book</div>
    <ul style="padding-left:18px;margin:0">${tipsList}</ul>
  </div>` : ''}
  ${g.if_conversation_stalls ? `<div style="background:#eff6ff;padding:14px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:5px">If energy drops</div>
    <div style="font-size:14px;color:#1e40af;line-height:1.6">${esc(g.if_conversation_stalls)}</div>
  </div>` : ''}
  ${pairings ? `<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f0eaf8">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:7px">Recommended pairings</div>
    ${pairings}
  </div>` : ''}
  <div style="background:#2d1b4e;color:#6b4a9e;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Book Club Discussion Generator · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, bookTitle: g.book_title, author: g.author, guide: g } }];
